INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(99, 'plPL', 'Głupota Arugala', 'Im lepiej rozumiem magię Arugala, tym większą pogardą darzę tego żałosnego głupca. Jestem bliski ukończenia badań nad jego tak zwanym lekarstwem.$b$bMoja wiedza będzie pełna, gdy ustalę, jakie zaklęcie wywołuje dziwne zachowanie mieszkańców Wioski Stosowego Lasu. Za dnia wieśniacy wyglądają na ludzi. Ale gdy zajdzie słońce, zmieniają się w worgeny Księżycowego Gniewu.$b$bMuszę zaczerpnąć energii z zaklętych kajdan, które Arugal na nich nałożył. Przynieś mi sześć zaklętych kajdan ze Stosowego Lasu, $N.', 'Przynieś 6 kajdan ze Stosowego Lasu Dalarowi Świtotkaczowi w Grobowisku.', '', 'Wróć do Dalara Świtotkacza w Grobowisku w Srebrzystym Borze.', '', '', '', '', 0),
(100, 'plPL', 'Zew wody', 'Gdy kończysz inkantację, wybucha światło. Odgłos kropel wody spadających na płomień cichnie, a gdy otaczające cię skażone duchy ulegają zniszczeniu, twoje zmysły ogarnia oszołomienie.', 'Porozmawiaj z pomniejszą manifestacją wody przy Północnym Nurcie Przypływu w Srebrzystym Borze.', '', '', '', '', '', '', 0),
(421, 'plPL', 'Dowiedź swojej wartości', 'Lady Sylwana powierzyła Varimathrasowi podbój ziem ludzi i krasnoludów na południu.$b$bAle ten głupiec Arugal – szarlatan z Dalaranu, a teraz przeklęta bestia z Twierdzy Cienistego Kła – pozwolił, by jego lekkomyślna magia spustoszyła Srebrzysty Bór, nasz strategiczny bastion.$b$bPotrzebuję kogoś biegłego w walce, kto pomoże posprzątać bałagan po Arugalu. Dowiedź mi swojej wartości i zabij 5 białołbów Księżycowego Gniewu. Te nędzne bestie często kręcą się tuż przy drodze, w dole zbocza.', 'Dalar Świtotkacz w Grobowisku chce, żebyś $gzabił:zabiła; 5 białołbów Księżycowego Gniewu.', '', 'Wróć do Dalara Świtotkacza w Grobowisku w Srebrzystym Borze.', '', '', '', '', 0),
(422, 'plPL', 'Głupota Arugala', 'Nie pojmuję, jak Arugal zdołał zostać przyjęty do Kirin Toru. Jego znajomość zaklęć była płytka i przejrzysta jak dmuchana szklana bombka.$b$bTeraz liczy się tylko to, by dokładnie ustalić, jakiej magii użył Arugal. Wtedy obrócę ją przeciwko niemu i zabezpieczę Srebrzysty Bór dla Mrocznej Pani.$b$bArugal najpierw zatrzymał się na farmie pszenicy tuż na północ od mostu. Jeden z tropicieli śmierci widział tam jakieś księgi zaklęć, ale nie zdołał ich zabrać. Znajdź w tych księgach zaklęcie zatytułowane Lekarstwo Arugala i przynieś mi je.', 'Zdobądź Lekarstwo Arugala dla Dalara Świtotkacza w Grobowisku.', '', 'Wróć do Dalara Świtotkacza w Grobowisku w Srebrzystym Borze.', '', '', '', '', 0),
(423, 'plPL', 'Głupota Arugala', 'Zbadanie dzieła Arugala potwierdziło moje najgorsze podejrzenia. Ten stary partacz nie nadawał się nawet do opróżniania nocników w Dalaranie, a co dopiero do reprezentowania Kirin Toru w jego najczarniejszej godzinie. Głupcy!$b$bArugal podpierał swoją słabą magię zaklętymi przedmiotami. Muszę je zbadać osobiście. Wyrusz i zabijaj żarłoków i mroczne dusze Księżycowego Gniewu, dopóki nie zbierzesz dość ich zaklętych kajdan do moich badań. Te plugawe stwory widywano na północy i na wschodzie.', 'Przynieś 6 kajdan żarłoka i 3 kajdany mrocznej duszy Dalarowi Świtotkaczowi w Grobowisku.', '', 'Wróć do Dalara Świtotkacza w Grobowisku w Srebrzystym Borze.', '', '', '', '', 0),
(424, 'plPL', 'Głupota Arugala', 'Odkrycie mrocznych tajemnic zaklęć, których używał Arugal, zajmie mi istotnie więcej czasu, niż sądziłem.$b$bTymczasem jednak musisz się zająć drobnym problemem, na który natrafili nasi tropiciele śmierci. Wygląda na to, że Arugal pozwolił, by jego magia rozlała się aż do Kopalni Głębi Elem na wzgórzach na południowym wschodzie.$b$bKopalnia byłaby cennym źródłem zaopatrzenia dla natarcia Varimathrasa.$b$bChcę, żebyś $gściął:ścięła; skażonego nadzorcę kopalni, Grimsona Bladego. Gdy zginie, kopalnia będzie nasza.', 'Zabij Grimsona Bladego i przynieś jego głowę Dalarowi Świtotkaczowi w Grobowisku.', '', 'Wróć do Dalara Świtotkacza w Grobowisku w Srebrzystym Borze.', '', '', '', '', 0),
(425, 'plPL', 'Ivar Plugawy', 'Mój brat Quinn i ja mieliśmy przeprowadzić zwiad w Srebrzystym Borze i złożyć raport najwyższemu egzekutorowi Hadrecowi. Ale daleko nie zaszliśmy – kiedy przechodziliśmy przez tę farmę, napadł nas ghul Ivar Plugawy.$B$BUciekliśmy Ivarowi, ale ciężko poturbował Quinna. Quinn zdrowieje po miksturze, którą mu $gdałeś:dałaś;, ale Ivar może wrócić, zanim mój brat wydobrzeje.$B$BZabij Ivara, żeby Quinn miał czas się wykurować. Ivar zwykle czai się w tamtej stodole i czeka, aż stracę czujność.', 'Zabij Ivara Plugawego i przynieś głowę Ivara Rane Yorick na Poletku Ivara.', '', 'Wróć do Rane Yorick w Srebrzystym Borze.', '', '', '', '', 0),
(428, 'plPL', 'Zaginieni tropiciele śmierci', 'Kilka tygodni temu wysłaliśmy dwoje naszych tropicieli śmierci, Rane i Quinna Yoricków, na zwiad przez północną część Srebrzystego Boru. Od tamtej pory milczą.$B$BMożliwe, że padli ofiarą Plagi, ale jeśli tak, chcę mieć na to potwierdzenie. Odnajdź tych tropicieli śmierci.$B$BNajpierw mieli przepatrzyć farmy na północy Srebrzystego Boru. Tam zacznij poszukiwania.', 'Odnajdź tropicieli śmierci Quinna i Rane Yoricków.', '', '', '', '', '', '', 0),
(429, 'plPL', 'Dzikie serca', 'Mojego brata Quinna ciężko poranił ghul Ivar Plugawy i nie wiem, czy wydobrzeje bez magicznej pomocy. Nie jestem aptekarką, ale wiem, że nasi aptekarze potrafią robić mikstury lecznicze z odbarwionych serc worgów.$B$BZbierz takie serca i zanieś je aptekarzowi Renferrelowi w Grobowisku na południu. Potem wróć tu z miksturą.$B$BMnóstwo worgów znajdziesz między tym miejscem a Sadem Maldena na wschodzie.', 'Zbierz 6 odbarwionych serc worgów i zanieś je aptekarzowi Renferrelowi w Grobowisku.', '', 'Wróć do aptekarza Renferrela w Grobowisku w Srebrzystym Borze.', '', '', '', '', 0),
(430, 'plPL', 'Powrót do Quinna', 'Oto mikstura, która pomoże Quinnowi Yorickowi wrócić do zdrowia.$B$BA teraz wybacz, muszę wrócić do bardzo ważnej pracy...', 'Zanieś miksturę Quinna Quinnowi Yorickowi na Poletku Ivara, na północ od Grobowiska.', '', '', '', '', '', '', 0),
(435, 'plPL', 'Eskorta Erlanda', 'Wilki na zewnątrz nie chcą odejść i łypią na mnie złowrogo, ilekroć wychylę nos za te drzwi. Muszą być potwornie głodne, skoro uważają, że warto mnie zjeść.$B$BMuszę się zameldować u mojej towarzyszki z oddziału, tropicielki śmierci Rane Yorick. A żeby do niej dotrzeć, potrzebuję pomocy przeciwko tym wilkom.$B$BProszę, eskortuj mnie! Wilków jest tam mnóstwo, więc będziemy mieli większe szanse, jeśli masz przyjaciół, którzy mogą pomóc...', 'Przeprowadź Erlanda przez wilki do Rane Yorick.', 'Erland musi dotrzeć do Rane Yorick', 'Wróć do Rane Yorick w Srebrzystym Borze.', '', '', '', '', 0),
(437, 'plPL', 'Martwe Pola', 'Pierwsze raporty zwiadowców ze Srebrzystego Boru wskazują, że Zgniłofutrzy mają bazę na starej farmie na północy, na Martwych Polach. Wysyłaliśmy przeciwko nim niewielkie oddziały, ale za każdym razem wspiera ich banshee Nocny Bicz, która swoją magią rozbija nasze siły.$B$BChcemy, żeby Nocny Bicz została zniszczona.$B$BIdź na Martwe Pola i zaatakuj Zgniłofutrych. Jeśli nie zobaczysz Nocnego Bicza, zabijaj Zgniłofutrych, aż się pojawi, a wtedy ją pokonaj.$B$BJej esencja obróci się w proch. Przynieś mi ten proch jako dowód.', 'Zabijaj gnole ze Zgniłofutrych na Martwych Polach.$B$BGdy pojawi się Nocny Bicz, zabij ją.$B$BPrzynieś esencję Nocnego Bicza najwyższemu egzekutorowi Hadrecowi w Grobowisku.', 'Wejdź na Martwe Pola', 'Wróć do najwyższego egzekutora Hadreca w Grobowisku w Srebrzystym Borze.', '', '', '', '', 0),
(438, 'plPL', 'Zniszczony Prom', '$N, odkryliśmy nowe gniazdo Plagi: Zniszczony Prom. Prom leży na wschód od Grobowiska i nieustannie patrolują go Zgniłofutrzy oraz inni nieumarli.$B$BPlaga musi mieć powód, by zajmować tę okolicę. Idź do Zniszczonego Promu i dowiedz się, co ją tam sprowadza.', 'Idź do Zniszczonego Promu.$B$BUstal, dlaczego jest tam Plaga.', '', '', '', '', '', '', 0),
(439, 'plPL', 'Tropy Zgniłofutrych', 'Spomiędzy zwłok wystaje dłoń, niezawinięta w całun. To dłoń kobiety, pokryta krostami po zarazie, ale stosunkowo świeża.$B$BNa palcu tkwi pierścień. Po zdjęciu go i obejrzeniu widać wygrawerowany napis:$B$B„Dla Deliah”', 'Zanieś pierścień Deliah najwyższemu egzekutorowi Hadrecowi w Grobowisku.', '', '', '', '', '', '', 0),
(442, 'plPL', 'Szturm na Wyspę Fenris', 'Nadszedł czas, by uderzyć na twierdzę Plagi w Srebrzystym Borze: Wyspę Fenris.$B$BMusisz znów udać się na wyspę i zniszczyć Thule\'a Kruczego Szponu. Chcę jego głowy!$B$BTa misja jest równie niebezpieczna, co ważna, $N. Nie możesz zawieść.', 'Przynieś głowę Thule\'a najwyższemu egzekutorowi Hadrecowi w Grobowisku.', '', 'Wróć do najwyższego egzekutora Hadreca w Grobowisku w Srebrzystym Borze.', '', '', '', '', 0),
(443, 'plPL', 'Posoka Zgniłofutrych', 'Zanim przypuścimy szturm na Wyspę Fenris, musimy ustalić, kto stoi za gnolami ze Zgniłofutrych. Nasi aptekarze uważają, że klucz do ich pochodzenia kryje dziwny płyn, który krąży w ich ciałach.$B$BUdaj się na Wyspę Fenris, na wschód od Zniszczonego Promu, i zbierz posokę Zgniłofutrych z tamtejszych gnoli. Zanieś ją aptekarzowi Renferrelowi, który stacjonuje przed Grobowiskiem.', 'Przynieś 8 buteleczek posoki Zgniłofutrych aptekarzowi Renferrelowi w Grobowisku.', '', 'Wróć do aptekarza Renferrela w Grobowisku w Srebrzystym Borze.', '', '', '', '', 0),
(448, 'plPL', 'Meldunek u Hadreca', 'Zanim przypuścisz szturm na Wyspę Fenris, zamelduj się u najwyższego egzekutora Hadreca. Może mieć dodatkowe informacje albo sprzęt, który ci się przyda.', 'Zamelduj się u najwyższego egzekutora Hadreca w Grobowisku.', '', '', '', '', '', '', 0),
(449, 'plPL', 'Raport tropicieli śmierci', 'Choć rany Quinna się goją, chcę jak najszybciej dostarczyć nasz raport najwyższemu egzekutorowi Hadrecowi. Zawiera informacje kluczowe dla okupacji Srebrzystego Boru przez Porzuconych.', 'Zanieś raport tropiciela śmierci najwyższemu egzekutorowi Hadrecowi w Grobowisku.', '', '', '', '', '', '', 0),
(452, 'plPL', 'Zasadzka w Stosowym Lesie', '$GZjawiłeś:Zjawiłaś; się w samą porę, $N!$b$bRada Stosowego Lasu wróci lada chwila. Arugal ma w twierdzy inne sprawy na głowie. Rada to dla niego tylko marionetki, dzięki którym trzyma w ryzach bezmyślne sługi ze Stosowego Lasu. Ale wierzę, że bez przewodnictwa Rady Stosowego Lasu synowie Arugala zwrócą się przeciwko swojemu panu.$b$bNie poradzę sobie z nimi wszystkimi sama. Musisz mi pomóc. Razem rozgromimy Radę dla lady Sylwany.', 'Pomóż tropicielce śmierci Faerlei zabić członków Rady Stosowego Lasu.', 'Pomóż Faerlei zabić członków Rady Stosowego Lasu', 'Wróć do tropicielki śmierci Faerlei w Wiosce Stosowego Lasu w Srebrzystym Borze.', '', '', '', '', 0),
(460, 'plPL', 'Spoczywaj w kawałkach', 'Nie wyglądasz na Zgniłofutrego. To dobrze. Już straciłem nadzieję...$B$BNazywam się Alaric. Byłem niegdyś głównym sługą i ochroniarzem Thule\'a. Swoją magią „chronił” mnie przed zarazą nieżycia, ale jego zaklęcie uwięziło mnie w nieżyciu, z którego nie mogę się wyrwać. A gdy stworzył przeklętych Zgniłofutrych, ściął mi głowę... i dał ją gnolom do zabawy!$B$BProszę, zanieś mnie do mojego ciała. Myślę, że gnole zakopały je tu, w Twierdzy Fenris, niedaleko stajni, w nieoznaczonym grobie.', 'Zanieś głowę Alarica do jego grobu.', '', '', '', '', '', '', 0),
(461, 'plPL', 'Ukryta nisza', 'Wiem o ukrytej niszy w twierdzy, w której leży przedmiot drogi Thule\'owi i jego dawnym kolegom. Jest tam też coś, co może ci się przydać. Zanieś mnie tam!$B$BWnęka jest w południowo-zachodniej wieży twierdzy, za zakurzoną półką.$B$BZabierz moje ciało, ale zostaw buty. I tak nigdy na mnie nie pasowały...', 'Zanieś Alarica do ukrytej wnęki.', '', '', '', '', '', '', 0),
(477, 'plPL', 'Przejścia graniczne', 'Jak zapewne wiesz, Żywiczny Tartak wciąż jest ośrodkiem ludzkiego oporu, głównie dzięki wsparciu czarodziejów z Dalaranu.$b$bNie wiem, jaki mają plan, ale skoro interesują się taką zapadłą dziurą jak Żywiczny Tartak, to miejsce musi mieć większe znaczenie.$b$bCałymi wozami zwożą skrzynie z Międzygórza. Wiele z tych zapasów trafia do małego obozu na północ od Wioski Stosowego Lasu. Zdobądź zawartość jednej ze skrzyń i przynieś mi ją.', 'Zdobądź zawartość jednej ze skrzyń czarodziejów z Dalaranu. Wioskę Stosowego Lasu znajdziesz na południu.', '', '', '', '', '', '', 0),
(478, 'plPL', 'Mapy i runy', '<Szybko wyjmujesz wisior ze skrzyni i zakładasz wieko z powrotem.>', 'Zanieś dziwny wisior kapłanowi cienia Allisterowi w Grobowisku.', '', '', '', '', '', '', 0),
(479, 'plPL', 'Śledztwo w Żywicznym Tartaku', 'Dalar próbuje ustalić, skąd czarodzieje czerpią moc do swoich zaklęć. Na razie musimy spowalniać ich postępy, jak tylko się da...$b$bPrzywoływacze, magowie i protektorzy bez wątpienia noszą przy sobie wisiory. Odbierz im je.$b$bIdź główną drogą na południe, a na rozwidleniu skręć na wschód, do Żywicznego Tartaku.', 'Zdobądź 8 dalarańskich wisiorów dla kapłana cienia Allistera w Grobowisku.', '', 'Wróć do kapłana cienia Allistera w Grobowisku w Srebrzystym Borze.', '', '', '', '', 0),
(480, 'plPL', 'Tkacz', 'Nad ponownym uruchomieniem węzła energii linii mocy czuwa arcymag wielkiej mocy. Przy postępach, jakie już poczynili, jedyną nadzieją na ich powstrzymanie jest zabicie go. Nie będzie łatwo – z pewnością chroni go wielu innych magów i stróżów.$b$bMusisz iść i szybko go wykończyć. Kiedy zginie, przynieś mi jego kostur. Idź już.', 'Zabij arcymaga z Dalaranu, a potem przynieś jego kostur kapłanowi cienia Allisterowi w Grobowisku.', '', 'Wróć do kapłana cienia Allistera w Grobowisku w Srebrzystym Borze.', '', '', '', '', 0),
(481, 'plPL', 'Analiza Dalara', 'Zanieś wisior Dalarowi Świtotkaczowi. Może rzuci trochę światła na plany czarodziejów.', 'Zanieś wisior z wyrytymi runami Dalarowi Świtotkaczowi w Grobowisku.', '', '', '', '', '', '', 0),
(482, 'plPL', 'Zamiary Dalaranu', 'Oczywiście! Jak mogłem zapomnieć?$b$bŻywiczny Tartak był jednym z miejsc wytypowanych przez Kirin Tor, bo znajduje się tam uśpiony węzeł energii linii mocy. Czarodzieje muszą planować ponowne uruchomienie węzła i wykorzystanie jego energii do jakiegoś większego celu.$b$bNie możemy do tego dopuścić...$b$bUruchomienie tutejszej energii linii mocy wymaga ogromnej siły. Możemy ich opóźnić, odbierając czarodziejom wisiory.$b$bPrzekaż te informacje Allisterowi, on zdecyduje, co robić.', 'Porozmawiaj z kapłanem cienia Allisterem w Grobowisku.', '', '', '', '', '', '', 0),
(493, 'plPL', 'Podróż do Międzygórza', 'Mroczna Pani wywiera na Królewskie Zakłady Chemiczne ogromną presję, byśmy opracowali Nową Zarazę. Pracujemy pilnie i poczyniliśmy spore postępy. Wierzymy, że sukces przyjdzie znacznie szybciej, jeśli będziemy się dzielić informacjami w obrębie Zakładów.$b$bDlatego chcę, żebyś $gdostarczył:dostarczyła; moje najnowsze wyniki badań aptekarzowi Lydonowi w Smolnym Młynie, niewielkim miasteczku w Międzygórzu. Podróż będzie długa.$b$bKieruj się na południe i trzymaj się dróg. Uważnie patrz na drogowskazy!', 'Dostarcz wyniki badań aptekarza Renferrela aptekarzowi Lydonowi w miasteczku Smolny Młyn w Międzygórzu.', '', '', '', '', '', '', 0),
(516, 'plPL', 'Niedola Berena', 'Doszły mnie meldunki, że grupa nieumarłych zaszyła się gdzieś i szykuje atak na nas. Znając ich zamiary, możemy odwrócić sytuację i uderzyć pierwsi, dusząc ich mały plan w zarodku.$b$bNiestety, moje informacje są w najlepszym razie wyrywkowe. Podobno kryją się w miejscu zwanym Niedolą Berena. Dokładne położenie jest nieznane, ale wygląda na to, że to jaskinia na wzgórzach, w pobliżu skupiska czarodziejów z Dalaranu.$b$bLiczę na twoją zaradność. Znajdź ich i zlikwiduj.', 'Odnajdź Niedolę Berena, zabij 6 harowników Kruczego Szponu i 6 strażników Kruczego Szponu, a potem wróć do kapłana cienia Allistera w Grobowisku.', '', 'Wróć do kapłana cienia Allistera w Grobowisku w Srebrzystym Borze.', '', '', '', '', 0),
(1005, 'plPL', 'Co czai się dalej', '', '', '', '', '', '', '', '', 0),
(1006, 'plPL', 'Co leży dalej', '', '', '', '', '', '', '', '', 0),
(1014, 'plPL', 'Arugal musi zginąć', 'Arugal wciąż przebywa w Twierdzy Cienistego Kła. Dopóki żyje, nie możemy uczynić Srebrzystego Boru strategicznym bastionem Mrocznej Pani.$b$bJa dopilnuję, by jego magia została wykorzeniona, $N. Ale w twoje ręce oddaję to, by Arugal spotkał śmierć, na którą tak zasłużył.$b$bUdaj się do Twierdzy Cienistego Kła i raz na zawsze połóż kres plugawym zaklęciom Arugala. Przynieś mi głowę tego nikczemnego czarodzieja!', 'Zabij Arugala i przynieś jego głowę Dalarowi Świtotkaczowi w Grobowisku.', '', 'Wróć do Dalara Świtotkacza w Grobowisku w Srebrzystym Borze.', '', '', '', '', 0),
(1098, 'plPL', 'Tropiciele śmierci w Cienistym Kle', 'Przed szturmem na Twierdzę Cienistego Kła wysłaliśmy tam dwóch tropicieli śmierci, by zebrali informacje. Minęło wiele dni, a oni nie wrócili, a jeśli atak ma mieć jakiekolwiek szanse powodzenia, musimy dostać ich raport!$B$BOto twoje zadanie, $N. Udaj się do Twierdzy Cienistego Kła na południu i odszukaj tropicieli śmierci Adamanta i Vincenta. Znajdź ich, a jeśli potrzebują pomocy, udziel jej.$B$BTa misja jest równie niebezpieczna, co ważna, $N. Nie zawiedź.', 'Odnajdź tropiciela śmierci Adamanta i tropiciela śmierci Vincenta.', '', '', '', '', '', '', 0),
(1103, 'plPL', 'Zew wody', 'Witaj, $gbracie:siostro;! Ty też $gprzyszedłeś:przyszłaś; oczyścić tutejsze wody i pokazać Islen, że rozumiesz?$B$BJa sam właśnie pokonałem skażonego ducha wody i zaraz kładę karwasze i resztę kropli wody na koszu żarowym.$B$BCo mówisz? Aaach. Tiev dobrze rozumie, jak coś idzie nie tak. No, Tiev dużo ci pomoże, jak znowu musisz zobaczyć czystego ducha wody.$B$BPrzynieś mi saptę wody od Islen na dowód, że jesteś $ggotowy:gotowa;, a ja poczekam z oddaniem moich rzeczy.', 'Przynieś saptę wody Tievowi Mordune\'owi w Srebrzystym Borze, jeśli nie udało ci się porozmawiać z pomniejszą manifestacją wody.', '', 'Wróć do Tieva Mordune\'a w Srebrzystym Borze.', '', '', '', '', 0),
(3221, 'plPL', 'Porozmawiaj z Renferrelem', 'Kiedy $gpomagałeś:pomagałaś; naszym tropicielom śmierci, aptekarz Renferrel przysłał po ciebie wezwanie. Nie podał mi szczegółów, ale chciał z tobą porozmawiać o wilczych sercach, które mu $gdałeś:dałaś;.', 'Porozmawiaj z aptekarzem Renferrelem w Grobowisku.', '', '', '', '', '', '', 0),
(6321, 'plPL', 'Zaopatrzenie dla Grobowiska', 'Egzekutor Hadrec polecił mi spisać nasz sprzęt w Grobowisku. Skoro w lasach czai się Plaga, i coś gorszego, nie chce, żeby strażnikom śmierci zabrakło potrzebnego wyposażenia.$B$BUstaliłem, że ogólnie jesteśmy dobrze zaopatrzeni, ale potrzebujemy więcej broni w miejsce tej utraconej w polu.$B$BOto zamówienie na to, czego trzeba, dla handlarza bronią Gordona Wendhama w Podmieście. Zanieś je naszemu treserowi nietoperzy, Karosowi Razokowi, i porozmawiaj z nim o transporcie do Podmiasta.', 'Zanieś rozkaz Podriga Karosowi Razokowi.', '', '', '', '', '', '', 0),
(8577, 'plPL', 'Stewvul, były BFF', 'Jeśli mam cokolwiek przetłumaczyć, potrzebuję moich wróżebnych gogli. Niestety, dawno temu ukradł je mój były najlepszy przyjaciel na zawsze, Stewvul. Złamał mi serce w pięciu miejscach, a potem zostawił mnie tu, żebym zgnił.$B$BZ pomocą mojej niezawodnej kryształowej kuli ustaliłem, że jest albo przy Murze Szarogrzywych w Srebrzystym Borze, albo w czymś, co wygląda na portalowy świat na Rubieży, który właśnie zalewa Płonący Legion. Musisz go wytropić i odzyskać moje gogle, $N!', 'Narain Wróżbiarz chce, żebyś $godnalazł:odnalazła; jego byłego najlepszego przyjaciela na zawsze (BFF),\n Stewvula, i $godebrał:odebrała; wróżebne gogle, które Stewvul mu ukradł.', '', '', '', '', '', '', 0),
(8578, 'plPL', 'Wróżebne gogle? Żaden problem!', '<Słyszysz, jak ze skrzyni wydobywa się westchnienie ulgi.>$B$BChcesz tylko jego wróżebnych gogli? Świetnie! To żaden problem... Daj mi tylko chwilę, żebym... Hej! Gdzie się... Psiakrew!$B$BNo więc mam złą wiadomość i jeszcze gorszą wiadomość. Zła jest taka, że zgubiłem gogle. Gorsza – że zgubiłem je, kiedy węszyłem w Ognistej Czeluści w zeszłym miesiącu. Tak, w Ognistej Czeluści... To chyba kończy nasze interesy! Pa!', 'Znajdź wróżebne gogle Naraina i zwróć je Narainowi Wróżbiarzowi w Tanaris.', '', 'Wróć do Naraina Wróżbiarza w Tanaris.', '', '', '', '', 0),
(8606, 'plPL', 'Podpucha!', 'Mam! Zrobimy tak. Napełnię worek kamieniami, a ty go podrzucisz. Wiem, że w liściku było napisane, że to ja mam dostarczyć okup, i tak zrobię – w pewnym sensie.$B$B<Narain mierzy cię wzrokiem od stóp do głów.>$B$BTak, świetnie się nadasz. Weź ten turban, szatę i worek kamieni i udaj się na miejsce przekazania w Zimozdroju.$B$BWszystko, czego potrzebujesz, jest w tym specjalnym zestawie. Gdy się zjawią, żeby odebrać towar, zlikwiduj ich! To ich nauczy zadzierać z Narainem!$B', 'Narain Wróżbiarz z Tanaris chce, żebyś $gudał:udała; się do Zimozdroju i $gzostawił:zostawiła; worek złota w miejscu przekazania wskazanym przez porywaczy książki.', '', 'Wróć do Naraina Wróżbiarza w Tanaris.', 'Dla kogo pracuje Numer Dwa?', '', '', '', 0),
(8620, 'plPL', 'Jedyne lekarstwo', 'Powinienem był się domyślić. Mój arcywróg, Doktor Weavil, znowu w swoim stylu! A teraz, dzięki twojej porażce w Zimozdroju, Doktor Weavil zniszczył moją książkę! Jak teraz ocalisz świat, $gbohaterze:bohaterko;?$B$BW liściku, który dostałem, napisano, że jedyny znany egzemplarz „Smoczego dla opornych: tom II” podarto na 8 części i rozrzucono na cztery wiatry! Jeśli jakimś cudem znajdziesz te zaginione rozdziały, połącz je za pomocą tej magicznej oprawy i wróć do mnie.', 'Odzyskaj 8 zaginionych rozdziałów „Smoczego dla opornych”, połącz je z magiczną oprawą książki i zwróć kompletną książkę „Smoczy dla opornych: tom II” Narainowi Wróżbiarzowi w Tanaris.', '', 'Wróć do Naraina Wróżbiarza w Tanaris.', '', '', '', '', 0),
(8645, 'plPL', 'Nestor Obsydian', '', '', '', '', '', '', '', '', 0),
(8728, 'plPL', 'Dobra wiadomość i zła wiadomość', 'No, trochę to trwało dłużej, niż się spodziewałem. A teraz zobaczmy, co jest w tej księdze.$B$B<Narain czyta księgę w milczeniu, co jakiś czas coś mrucząc pod nosem.>$B$BDobra wiadomość jest taka, że na 99% jestem w stanie stworzyć arkanitową boję, która będzie działać zgodnie z twoimi wymaganiami. Wszystko to, rzecz jasna, zależy od złej wiadomości.$B$BA zła wiadomość jest taka, że będę potrzebował mnóstwa arkanitu, rudy elementium i rzadkich klejnotów.$B$BPrzynieś mi to, czego potrzebuję, a zrobię boję.', 'Narain Wróżbiarz z Tanaris chce, żebyś $gprzyniósł:przyniosła; mu 20 sztabek arkanitu, 10 bryłek rudy elementium, 10 azerothiańskich diamentów i 10 niebieskich szafirów.', '', 'Wróć do Naraina Wróżbiarza w Tanaris.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(99, 'plPL', 'Twoja wytrwałość zasługuje na uznanie. Dzięki wiedzy, którą $gpomogłeś:pomogłaś; mi zebrać, Arugal upadnie, a jego lekkomyślna magia zostanie zniweczona. Twoje zdrowie, $N.', 0),
(100, 'plPL', 'Dzięki tobie. Dzięki szamanom.$B$BSkażenie słabnie, ale życie wciąż gaśnie. Chronić życie – to zadanie szamanów.', 0),
(421, 'plPL', 'Dobrze mi $gsłużyłeś:służyłaś;, $N. Nie mam wątpliwości, że okażesz się godnym wsparciem, gdy będę się przygotowywał do oczyszczenia Srebrzystego Boru z klątwy Arugala.', 0),
(422, 'plPL', 'To dokładnie to zaklęcie, którego szukałem, $N. Jeśli twoje oddanie sprawie Mrocznej Pani pozostanie niezachwiane, przekonasz się, że wśród Porzuconych czeka cię niemała przyszłość.', 0),
(423, 'plPL', 'Mam nadzieję, że z tak skromnej próbki zdołam wydobyć dość energii. Może powinienem był kazać ci przynieść więcej kajdan.$b$bTak czy owak, $gwykazałeś:wykazałaś; się wielką zręcznością przy ich zbieraniu, $N.', 0),
(424, 'plPL', 'Znakomicie. Kopalnia zapewni naszym siłom doskonałe zasoby, gdy będziemy się rozlewać po Srebrzystym Borze i dalej, w głąb Azeroth.', 0),
(425, 'plPL', 'Ach, dziękuję. Masz moją wdzięczność, $N.$b$bWspomnę o tobie w raporcie dla przełożonych.', 0),
(428, 'plPL', '$GZnalazłeś:Znalazłaś; nas! I to w ostatniej chwili...', 0),
(429, 'plPL', '<Renferrel bierze serca>$b$bNiepokojące wieści – nasi tropiciele śmierci nie wykonali misji.$b$bMiejmy nadzieję, że takie porażki zdarzają się rzadko.$b$bZa chwilę dam ci miksturę, ale weź też jej recepturę. Jeśli ci tropiciele śmierci znów będą potrzebować pomocy, może zdołasz im jej udzielić bez mojego udziału.', 0),
(430, 'plPL', '<Quinn bierze miksturę i ją wypija>$b$bTak, czuję, jak działa. Niedługo będę mógł ruszyć w drogę.$b$b$GWyświadczyłeś:Wyświadczyłaś; mi wielką przysługę, $N.', 0),
(435, 'plPL', 'Dziękuję za pomoc, $N. Bałam się, że Erland padł ofiarą niebezpieczeństw Srebrzystego Boru. Dzięki tobie widzę, że tak się nie stało.', 0),
(437, 'plPL', 'Słyszałem o twoim udanym wypadzie przeciw Zgniłofutrym, $N, a ta esencja dowodzi śmierci Nocnego Bicza.$b$bPlaga straciła dziś grunt pod nogami. Twoja wartość dla Porzuconych rośnie.', 0),
(438, 'plPL', 'W łodzi piętrzy się stos zawiniętych w całuny zwłok. Gdy spojrzeć na wschód, przez Jezioro Lordamere, widać przystań po drugiej stronie, na Wyspie Fenris.$B$BLos tych zwłok musi się wiązać z Wyspą Fenris.', 0),
(439, 'plPL', 'Mówisz, że ten pierścień nosiła kobieta, która niedawno zmarła?$B$BJedynym pobliskim źródłem takich ciał są Zbiorowe Mogiły w Tirisfal. Gnole ze Zgniłofutrych muszą wywozić te zwłoki na Wyspę Fenris!', 0),
(442, 'plPL', 'Śmierć Thule\'a Kruczego Szponu to nie byle co, $N. Renferrel mówi, że energię uwolnioną, gdy $gzniszczyłeś:zniszczyłaś; Thule\'a, czuć było aż w Grobowisku.$b$bTwoje czyny odbijają się echem w szeregach Porzuconych. Twoja wartość dla nas rośnie.', 0),
(443, 'plPL', 'Bardzo dobrze. Ta posoka pomoże nam zrozumieć naturę Zgniłofutrych i może wskaże ich słabość...$b$b...o ile w ogóle jakąś mają.', 0),
(448, 'plPL', 'Jeśli Bethor mówi prawdę, Thule Kruczy Szpon to siła, z którą trzeba się rozprawić, i to szybko.$b$bAby ci w tym pomóc, pozwolę ci wziąć coś z naszego arsenału...', 0),
(449, 'plPL', 'Nie spodziewałem się tak silnej obecności Plagi w Srebrzystym Borze ani kłopotów, jakie napotkali nasi tropiciele śmierci podczas zwiadu.$b$bTwoja pomoc dla naszych tropicieli śmierci była bezcenna, $N. Dostaniesz za nią pochwałę.', 0),
(452, 'plPL', '$GWalczyłeś:Walczyłaś; jak $gprawdziwy uczeń:prawdziwa uczennica; Mrocznej Pani, $N. Skoro rada nie żyje, może wreszcie przejmiemy to miasteczko na dobre i wypędzimy Arugala z Twierdzy Cienistego Kła. Oddaję ci honor!', 0),
(460, 'plPL', 'Dziękuję, $N. Bałem się, że gnole zniszczyły moje ciało. Dobrze wiedzieć, że tak się nie stało.', 0),
(461, 'plPL', 'No i proszę, otwarte. Zostaw mnie tutaj. Spędziłem w tej twierdzy najlepsze dni życia, a myśl, że spocznę w jej murach, przynosi mi pociechę.$b$bPamiętaj, żeby szczelnie zamknąć wnękę – nie chcę, żeby znaleźli mnie ci Zgniłofutrzy.$b$bA, i weź to. $GZasłużyłeś:Zasłużyłaś;.', 0),
(477, 'plPL', '<Podważasz wieko skrzyni i znajdujesz w niej starannie zapakowane przedmioty. Na wierzchu leży plik pożółkłych ze starości map, które zdają się przedstawiać Srebrzysty Bór i inne części zachodniego Lordaeronu.$b$bPod mapami leży tajemniczo wyglądający magiczny wisior.>', 0),
(478, 'plPL', 'Mapy i ten... wisior, hm? Ciekawe.$b$bOczywiste, że czarodzieje z Dalaranu interesują się Żywicznym Tartakiem w jakimś celu, ale ten cel wciąż pozostaje dla mnie ukryty.$b$bMoże Dalar będzie wiedział, do czego to służy.', 0),
(479, 'plPL', 'Dalar ustalił, że mimo tej przeszkody splatanie zaklęcia jest już mocno zaawansowane.$b$bMagiczną energią kieruje czarodziej wielkiej mocy. Trzeba go szybko powstrzymać.', 0),
(480, 'plPL', 'Magia czarodziejów się rozprasza, a energia linii mocy zapada w uśpienie. Twój trud się opłacił, $N. Zadaliśmy poważny cios naszym wrogom i tym wyniosłym czarodziejom z Dalaranu.$b$bMusimy jednak zachować czujność, skoro takie źródło energii jest tuż pod ręką... Trzeba poczynić plany na przyszłość.', 0),
(481, 'plPL', 'Ciekawe. Wygląda na to, że to kolejne machinacje Kirin Toru. To potężny artefakt. Potężni czarodzieje Kirin Toru często używali go do kanalizowania magicznej energii.$b$bSkoro dostarczają ich tyle do Żywicznego Tartaku, muszą prowadzić jakieś przedsięwzięcie na dużą skalę.$b$bSprawdzę, czy zdołam przebić się przez ich osłony i ustalić, co zamierzają.', 0),
(482, 'plPL', 'Złe wieści przynosisz, $N. Jeśli Dalar ma rację – a nie mam powodu sądzić, że się myli – musimy działać szybko.$b$bMuszę omówić z nim plan ataku. A tymczasem trzeba opóźnić ich postępy.', 0),
(493, 'plPL', 'Ach, wyśmienicie. Aptekarz Renferrel cieszy się moim najwyższym szacunkiem. Nie mogę się doczekać, aż zbadam jego pracę.', 0),
(516, 'plPL', 'Jeśli nasi zwiadowcy i agenci nadal będą zdobywać tak cenne informacje, w mgnieniu oka usuniemy Plagę Króla Lisza z naszych ziem.', 0),
(1014, 'plPL', 'Srebrzysty Bór wreszcie wyrwał się z uścisku tego nędznika Arugala. $GOddałeś:Oddałaś; Mrocznej Pani wielką przysługę, $N. Twoja nieustępliwość zostanie nagrodzona.', 0),
(1098, 'plPL', 'Ciało Vincenta leży połamane i nieruchome.$b$bChoć tropiciel śmierci Adamant prześle Hadrecowi swój raport... wszystko, czego jeszcze dowiedział się Vincent, pozostanie z nim na zawsze.$b$bAle w jego dłoni tkwi zaciśnięty mały bibelot...', 0),
(1103, 'plPL', 'Aaach, to już jesteś $ggotowy:gotowa;...$B$BTo ja włożę moje rzeczy do kosza, a ty też pogadasz z duchem.$B$BI nic się nie martw, że z saptą zajrzysz do świata duchów... stary Tiev zna parę sztuczek, jak ta magia sapty działa.$B$BChodź, zejdź ze mną do kapliczki i pogadajmy razem z duchami, $gbracie:siostro;.', 0),
(3221, 'plPL', 'Ach, bardzo dobrze. Pewna sprawa dotycząca wilczych serc, które mi wcześniej $gprzyniosłeś:przyniosłaś;, wymaga naszej uwagi.', 0),
(6321, 'plPL', 'Ach, zamówienie na zaopatrzenie. Bez wątpienia zechcesz zanieść to do Podmiasta. I to szybko, bo Grobowisko nie może zostać bez zapasów.', 0),
(8577, 'plPL', 'Nie wierzę, że mnie znalazł. Byłem pewien, że zgubiłem go na Rubieży. Nie wracam tam! Nie ma mowy, za nic w świecie! Mam dość bycia jego najlepszym przyjacielem na zawsze na pół etatu i niewolnikiem na pełen etat.', 0),
(8578, 'plPL', 'Rewelacja! A gdzie ja położyłem tego pięćsetfuntowego kurczaka i tom II „Smoczego dla opornych”??? A, i tu masz coś drobnego za całą twoją ciężką pracę!', 0),
(11580, 'plPL', 'Zbezcześć wielkie ognisko Hordy w Srebrzystym Borze!', 0),
(11584, 'plPL', 'Uczcij płomień Srebrzystego Boru!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(99, 'plPL', '$GZdobyłeś:Zdobyłaś; już kajdany ze Stosowego Lasu, $N?', 0),
(421, 'plPL', 'Jeśli chcesz się przede mną wykazać, musisz zabić 5 białołbów Księżycowego Gniewu. Wykonaj to zadanie, a dopilnuję, by twoje umiejętności wykorzystano przy godniejszych zleceniach.', 0),
(422, 'plPL', 'Zanim zrozumiem, z czym mamy tu do czynienia, $N, muszę zbadać zaklęcie zwane Lekarstwem Arugala. Przynieś mi je natychmiast, bo inaczej będę zmuszony poszukać sobie godniejszego sługi.', 0),
(423, 'plPL', 'Potrzebuję 6 kajdan żarłoka i 3 kajdan mrocznej duszy, zanim ocenię sytuację i obmyślę ostateczne rozwiązanie kwestii Arugala. A teraz rób, co ci każę, i zabijaj żarłoków i mroczne dusze Księżycowego Gniewu, dopóki nie zdobędziesz tego, czego potrzebuję.', 0),
(424, 'plPL', 'Czy Grimson Blady już nie żyje? Varimathras nie będzie zadowolony, jeśli zlekceważymy jego rozkazy.', 0),
(425, 'plPL', '$GZabiłeś:Zabiłaś; Ivara Plugawego? Jeśli nie zrobisz tego dla mnie i mojego brata, zrób to dla Porzuconych.', 0),
(429, 'plPL', 'Mam mało czasu, $N, bo Mroczna Pani powierzyła mi zadanie najwyższej wagi.', 0),
(430, 'plPL', 'Siostra mówiła, że $gprzybyłeś:przybyłaś; nam pomóc. To prawda?', 0),
(437, 'plPL', '$GPokonałeś:Pokonałaś; Nocnego Bicza, $N? Nasze zwycięstwo nad Zgniłofutrymi zależy od jej zniszczenia!', 0),
(439, 'plPL', '$N. Wracasz, więc zakładam, że twoje dochodzenie przyniosło owoce?', 0),
(442, 'plPL', 'Nie możemy pozwolić, by Plaga pozostała w Srebrzystym Borze, $N. Wróć do mnie, gdy będziesz mieć dowód śmierci Thule\'a.', 0),
(443, 'plPL', 'Masz posokę Zgniłofutrych, $N?', 0),
(449, 'plPL', '$GOdkryłeś:Odkryłaś;, co się stało z tropicielami śmierci?', 0),
(460, 'plPL', 'Ten grób wykopano w pośpiechu.', 0),
(461, 'plPL', 'To tutaj! Przybliż mnie...', 0),
(478, 'plPL', '$GDowiedziałeś:Dowiedziałaś; się czegoś przydatnego, $N?', 0),
(479, 'plPL', 'Musimy się spieszyć. Ich plany nie mogą się ziścić, bo inaczej możemy stracić władzę nad Srebrzystym Borem.', 0),
(480, 'plPL', 'Szybko, czas ucieka, $N!', 0),
(481, 'plPL', 'Tak, $N? O co chodzi?', 0),
(516, 'plPL', '$GZnalazłeś:Znalazłaś; już ich bazę, $N? Czas nagli!', 0),
(1014, 'plPL', 'Śmierć Arugala pozwoli nam umocnić władzę Mrocznej Pani nad Lordaeronem.', 0),
(1103, 'plPL', 'Masz saptę, $gbracie:siostro;?$B$BZnam jednego, co miał kłopot po pokonaniu skażonego ducha wody – chyba za długo czekał i za szybko wyleciał ze świata duchów, jak na jego gust. Nie chcę, żeby komuś innemu to się stało, to jeszcze trochę tu poczekam, czy ktoś nie potrzebuje mojej pomocy.', 0),
(6321, 'plPL', 'Wyglądasz, jakbyś $gprzyszedł:przyszła; w sprawach służbowych...', 0),
(8578, 'plPL', 'Ognista Czeluść, co? Mam nadzieję, że moje gogle są jeszcze w jednym kawałku!', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(1938, 0, 'plPL', 'Kirin Tor nie posłuchał moich ostrzeżeń! Przymierze to farsa. Arugal to lekkomyślny głupiec.', 0),
(1950, 0, 'plPL', 'Mój brat i ja mamy ważną misję, ale utknęliśmy w tym domu. Tropiciele śmierci potrzebują twojej pomocy.', 0),
(2121, 0, 'plPL', 'Informacja... Dzięki naszym zwiadowcom i agentom panujemy nad przepływem informacji w Lordaeronie. Ruchy Plagi, jej posiadłości – wszystko pod naszym czujnym okiem...', 0);
