INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(380, 'plPL', 'Raport z misji tropicieli śmierci. Agenci: Rane Yorick, Quinn Yorick, Erland McKree. Główna misja: przeprowadzić zwiad w północnej części Srebrzystego Boru i ocenić zagrożenie ze strony dzikich zwierząt i Plagi. ', 0),
(381, 'plPL', 'Agenci rozpoczęli przeczesywanie terenu i stwierdzili znaczną obecność worgów. Zalecamy wysłanie oddziałów łowieckich w celu ograniczenia tego zagrożenia. Nieumarłe gnole wykryto w gospodarstwie zwanym Martwym Polem. Ich cel w gospodarstwie jest nieznany, choć ich ruchy i stopień gotowości wskazują na rychłe działania zbrojne. W czasie obserwacji nie wykryto wśród gnoli żadnych znaczących przywódców. Zakłada się, że czekają na przybycie dowództwa lub posiłków. ', 0),
(382, 'plPL', 'W trakcie dalszego przeczesywania terenu nasi agenci zostali zatrzymani na farmie Ivara. Ivar, większość jego rodziny i jego robotnicy ulegli Pladze i stali się jej sługami. Nasi agenci zostali zaatakowani i choć pokonali napastników, odnieśli poważne obrażenia, zwłaszcza agent Quinn. ', 0),
(383, 'plPL', 'Zajęto pozycję obronną w starym domu Ivara i podczas gdy Rane wypatrywała kolejnych ataków, Erland kontynuował misję zwiadowczą. Erland został następnie osaczony przez worgi w sadzie na północy i uszedł tylko dzięki pomocy innego agenta Porzuconych. Tenże agent jest okazicielem niniejszego raportu. ', 0),
(386, 'plPL', 'Należy tu zaznaczyć, że okaziciel raportu walnie przyczynił się nie tylko do powodzenia naszej misji, ale także do pokonania Ivara Plugawego, ocalenia Erlanda i dostarczenia niniejszego raportu. Wyrażamy wdzięczność i zalecamy, by dowództwo uhonorowało tę osobę odznaczeniami godnymi tak chwalebnej postawy, jaką wykazała w polu. – Tropicielka śmierci Rane Yorick, dowódczyni misji ', 0),
(690, 'plPL', 'Na starannie wyrytym epitafium ktoś niezdarnie wydrapał słowo ZDRAJCA. Epitafium głosi:\n\nTu spoczywa Yuriv.\nOjciec, mąż, paladyn.\nNiech jego dzieci zaświadczą, że jego oddanie Światłu było niepodważalne.\nNigdy nie żądał od nich niczego, czego sam by nie uczynił.\n', 0);
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(4444, 0, 0, 'plPL', 'Aaargh!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(481, 'plPL', 'Chodźmy do pozostałych i miejmy oko na te wilki na zewnątrz...', '', 0),
(482, 'plPL', 'Uważaj, $n. Te wilki lubią się chować między drzewami.', '', 0),
(483, 'plPL', 'Już prawie jesteśmy!', '', 0),
(484, 'plPL', 'Udało się! Dzięki, $n. Bez ciebie bym tu nie dotarł.', '', 0),
(502, 'plPL', 'Synowie Arugala powstaną przeciw każdemu, kto rzuci wyzwanie potędze Księżycowego Gniewu!', '', 0),
(534, 'plPL', '', 'Dobrze cię znowu widzieć, Erlandzie. Jaki masz meldunek?', 0),
(535, 'plPL', 'Na wschodzie roi się od wilków, a ktokolwiek mieszkał w Sadzie Maldena, już go tam nie ma.', '', 0),
(536, 'plPL', 'Jeśli mogę odejść, chciałbym zajrzeć do Quinna...', '', 0),
(537, 'plPL', 'Cześć, Quinn. Jak się trzymasz?', '', 0),
(538, 'plPL', 'Postaraj się bardziej na siebie uważać, Quinn. Tym razem miałeś szczęście.', '', 0),
(539, 'plPL', 'Bywało lepiej. Ivar Plugawy mnie dopadł...', '', 0),
(541, 'plPL', 'Uwaga! $n nas atakuje!', '', 0),
(542, 'plPL', '', 'Bądź $ggotowy:gotowa;, $n. Słyszę, że rada wraca. Szykuj się do zasadzki!', 0),
(543, 'plPL', '$n atakuje!', '', 0),
(544, 'plPL', 'Uwaga! Atakują mnie!', '', 0),
(545, 'plPL', '', 'Dobra robota. Bez wątpienia cios dla Arugala!', 0),
(1869, 'plPL', 'Grrrrr!', '', 0),
(2588, 'plPL', 'Czego chcesz, $N? Jestem spóźniony, a mój pracodawca nie patrzy przychylnie na spóźnialskich.', '', 0),
(2589, 'plPL', 'Jesteś Astor Hadren, prawda?', 'Jesteś Astor Hadren, prawda?', 0),
(2590, 'plPL', 'Tak, to ja. A co ci do tego?', '', 0),
(2591, 'plPL', 'Masz coś, czego potrzebuję, Astor. I zaraz mi to oddasz.', 'Masz coś, czego potrzebuję, Astor. I zaraz mi to oddasz.', 0),
(5749, 'plPL', '', 'Przerywając mi, zabierasz mój cenny czas. Lepiej, żeby to było coś ważnego.', 0),
(11064, 'plPL', '<Narain przykłada do czoła nieotwartą kopertę.>$B$BCo to jest... Mmmm... Aksamit!$B$BZgadłem?$B$BJeśli chcesz ponownie nauczyć się jakiegoś rzemiosła, skorzystaj z tamtej księgi...$B$B<Narain wskazuje na „Wróżenie dla opornych”.>', '', 0),
(11065, 'plPL', 'Nic nie mów! Ciii! Przychodzisz w sprawie Spopielacza?!? Tak... Tak... Nie! Pomyłka.$B$BW czym mogę pomóc?$B$BJeśli chcesz ponownie nauczyć się jakiegoś rzemiosła, skorzystaj z tamtej księgi...$B$B<Narain wskazuje na „Wróżenie dla opornych”.>', '', 0),
(11066, 'plPL', 'Narain Wróżbiarz do usług! Emerytowany inżynier i mistrz wróżbiarstwa! Przepowiem twoją przyszłość, zanim w ogóle się wydarzy!$B$BJeśli chcesz ponownie nauczyć się jakiegoś rzemiosła, skorzystaj z tamtej księgi...$B$B<Narain wskazuje na „Wróżenie dla opornych”.>', '', 0),
(11501, 'plPL', 'Gdzie jest Nestor Wysoki Szczyt?', 'Gdzie jest Nestor Wysoki Szczyt?', 0),
(11502, 'plPL', 'Nestor Wysoki Szczyt czuwa nad Zaziemiem ze wzgórza w pobliżu jego środka.', 'Nestor Wysoki Szczyt czuwa nad Zaziemiem ze wzgórza w pobliżu jego środka.', 0),
(26865, 'plPL', 'Powstań, Arugalu! Rozkazuje ci moc Króla Lisza!', '', 0),
